// The symbol, kaomoji and emoji lists (generated by tools/generate_panel_data.py)
// in one shape: groups for the category bar, each with titled sections.
import type { PanelKind } from './types';

export type Item = { c: string; n?: string; k?: string[] };
export type Section = { name?: string; items: Item[] };
export type Group = { id: string; name: string; sections: Section[] };
export type Catalog = { kind: PanelKind; groups: Group[]; byValue: Map<string, Item> };

type SymbolFile = { groups: { id: string; name: string; sections: { name: string; items: Item[] }[] }[] };
type EmojiFile = { groups: { id: string; name: string; items: Item[] }[] };
type KaomojiFile = { groups: { id: string; name: string; items: string[] }[] };

function catalog(kind: PanelKind, groups: Group[]): Catalog {
  const byValue = new Map<string, Item>();
  for (const group of groups) for (const section of group.sections) for (const item of section.items)
    if (!byValue.has(item.c)) byValue.set(item.c, item);
  return { kind, groups, byValue };
}

const cache = new Map<PanelKind, Promise<Catalog>>();

export function loadCatalog(kind: PanelKind): Promise<Catalog> {
  let loading = cache.get(kind);
  if (!loading) {
    loading = kind === 'symbol'
      ? import('./data/symbols.json').then(module => {
          const file = module.default as SymbolFile;
          return catalog(kind, file.groups.map(group => ({ id: group.id, name: group.name, sections: group.sections })));
        })
      : kind === 'emoji'
        ? import('./data/emoji.json').then(module => {
            const file = module.default as EmojiFile;
            return catalog(kind, file.groups.map(group => ({ id: group.id, name: group.name, sections: [{ items: group.items }] })));
          })
        : import('./data/kaomoji.json').then(module => {
            const file = module.default as KaomojiFile;
            return catalog(kind, file.groups.map(group => ({ id: group.id, name: group.name,
              sections: [{ items: group.items.map(c => ({ c, n: group.name })) }] })));
          });
    cache.set(kind, loading);
  }
  return loading;
}

// U+2248, or U+1F600 U+FE0F for a sequence.
export function codePoints(value: string) {
  return [...value].map(ch => 'U+' + ch.codePointAt(0)!.toString(16).toUpperCase().padStart(4, '0')).join(' ');
}

export function matches(item: Item, query: string) {
  if (item.c.includes(query)) return true;
  if (item.n?.toLowerCase().includes(query)) return true;
  return !!item.k?.some(word => word.toLowerCase().includes(query));
}

// Chinese names an emoji is typed by, for offering it among candidates.
export function emojiNames(item: Item | undefined): string[] {
  if (!item) return [];
  const names = [item.n ?? '', ...(item.k ?? [])].filter(name => /^[㐀-鿿]{2,6}$/.test(name));
  return [...new Set(names)].slice(0, 3);
}
